//! SC-007: a deliberate 100 Hz shift of a band edge toward the band is caught by both the
//! response check and the golden check (spec 004 tasks.md T024; research R-06). Three fixtures,
//! generated by `tools/filter-design/design_voiceband.py --shift-*`: the record high-pass up
//! 100 Hz, the record low-pass stopband edge down 100 Hz, the playback low-pass down 100 Hz.

#[path = "fixtures/shifted_playback_lp_down100.rs"]
mod playback_lp;
#[path = "fixtures/shifted_record_hp_up100.rs"]
mod record_hp;
#[path = "fixtures/shifted_record_lp_down100.rs"]
mod record_lp;

use rr_dr60::{Pipeline, Settings};
use rr_dr60_harness::checks::{self, Stage};
use rr_dr60_harness::golden;

fn record_hp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_hp::SHIFTED_RECORD_SOS,
        record_hp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn record_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_lp::SHIFTED_RECORD_SOS,
        record_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn playback_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        playback_lp::SHIFTED_RECORD_SOS,
        playback_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn failed_properties(results: &[rr_dr60_harness::checks::MeasurementResult]) -> Vec<&'static str> {
    results
        .iter()
        .filter(|r| !r.passed)
        .map(|r| r.property)
        .collect()
}

/// Spec 004 SC-007 (research R-06): each toward-band shift fails its stage's template on the
/// row the shift moves. The record high-pass up 100 Hz breaks the 225–2250 Hz loss maximum;
/// a low-pass stopband edge down 100 Hz breaks the loss at 2550 Hz (about 9–11 dB).
#[test]
fn record_hp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_hp_mutant,
    ));
    assert!(
        failed.contains(&"loss 225-2250 Hz (max)"),
        "record high-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn record_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "record low-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn playback_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Playback,
        &playback_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "playback low-pass shift not caught; failures: {failed:?}"
    );
}

/// Spec 004 SC-007: each mutant also fails the spec 001 golden check against the committed
/// file, which is the 6 kHz re-bless of T038 (the unmutated pipeline matches it, see
/// `tests/golden.rs`), so a failure here means the mutation changed the output, not the rate.
#[test]
fn golden_check_catches_shifted_band_edges() {
    let expected = golden::committed();
    for (name, mutant) in [
        ("record hp", record_hp_mutant as fn(Settings) -> Pipeline),
        ("record lp", record_lp_mutant),
        ("playback lp", playback_lp_mutant),
    ] {
        let actual = golden::generate(&mutant);
        let report = golden::compare(&expected, &actual).expect_err(name);
        assert!(
            report.contains("sweep_log/default/48000 Hz differs"),
            "{name}: {report}"
        );
    }
}

/// Spec 002 SC-008: a deliberate change of the default release time by 50 %, or of the target
/// level by 3 dB, is caught by both a tolerance check and the AGC golden check. The mutants are
/// built through the harness's `Make` factory with altered public settings (research.md R-12).
mod agc {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::agc_checks;
    use rr_dr60_harness::golden;

    fn release_x1_5(mut s: Settings) -> Pipeline {
        s.agc.release_ms *= 1.5;
        Pipeline::new(s).unwrap()
    }

    fn target_plus_3(mut s: Settings) -> Pipeline {
        s.agc.target_dbfs += 3.0;
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn release_change_is_caught() {
        let defaults = agc_checks::matrix()[0];
        let failed = failed_properties(&agc_checks::check_fr006_timing(
            48_000,
            &defaults,
            &release_x1_5,
        ));
        assert!(
            failed.contains(&"release time"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_agc(),
            &golden::generate_agc(&release_x1_5),
        );
        assert!(diff.is_err(), "AGC golden check missed the release change");
    }

    #[test]
    fn target_change_is_caught() {
        let defaults = agc_checks::matrix()[0];
        let failed = failed_properties(&agc_checks::check_fr004_regulation(
            48_000,
            &defaults,
            &target_plus_3,
        ));
        assert!(
            failed.contains(&"output level on the regulation line"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_agc(),
            &golden::generate_agc(&target_plus_3),
        );
        assert!(diff.is_err(), "AGC golden check missed the target change");
    }
}

/// Spec 003 SC-007: a deliberate change of the default hang time by 20 %, or of the threshold
/// by 3 dB, is caught by both a tolerance check and the VAS golden check. The mutants are built
/// through the harness's `Make` factory with altered public settings, with no hidden hooks.
mod vas {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::golden;
    use rr_dr60_harness::vas_checks;

    fn hang_x1_2(mut s: Settings) -> Pipeline {
        s.vas.hang_ms *= 1.2; // 20 %, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn threshold_plus_3(mut s: Settings) -> Pipeline {
        s.vas.threshold_dbfs += 3.0; // 3 dB, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn hang_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed =
            failed_properties(&vas_checks::check_fr008_hang(48_000, &defaults, &hang_x1_2));
        assert!(
            failed.contains(&"kept part of the gap"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(&golden::committed_vas(), &golden::generate_vas(&hang_x1_2));
        assert!(diff.is_err(), "VAS golden check missed the hang change");
    }

    #[test]
    fn threshold_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed = failed_properties(&vas_checks::check_fr006_threshold(
            48_000,
            &defaults,
            &threshold_plus_3,
        ));
        assert!(
            failed.contains(&"threshold at 1 kHz − nominal"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_vas(),
            &golden::generate_vas(&threshold_plus_3),
        );
        assert!(
            diff.is_err(),
            "VAS golden check missed the threshold change"
        );
    }
}
